# Batch 5 (A-041 .. A-050) – "ULTRA HARD", sirf REELS (har case 5 suspect). Batch 4 se bhi mushkil:
#  - TRAP: kai masoom log aisi baat bolte hain jo GALAT lagti hai par SACH hai (Matheran mein gaadi nahi, Leh mein paani kam garmi
#    mein ubalta, Hornbill December mein, raat ko dhabe/airport khule...). Viewer ko har baat jaanchni padti hai.
#  - Kaatil ka jhooth chhota aur seedha-saadha, baaki jaisa hi. Kai case mein do saboot/fact jodne padte hain.
# Patterns (max 2): record + logic (2), time ka fact (1), date + fact (1), code (2), takraav (1), tasveer (1), bahar ka bayaan + trap (1),
# cheez thi hi nahi (1). Kaatil card: 4,2,5,1,3,5,4,1,2,3.
# Suspect: (naam_dev, shak_dev, bayaan_dev, naam_rom, shak_rom, bayaan_rom, look_en, emotion_tag – reels mein use nahi)
BATCH = 5
MIN_TAGS = True

def S(dev, shak_dev, line_dev, rom, shak_rom, line_rom, look):
    return (dev, shak_dev, line_dev, rom, shak_rom, line_rom, look, "")
def P(asset, prompt, clue=False): return (asset, prompt, "S2_11" if clue else "S2_04", clue)
JAGAH = "शिवम ने हर चीज़ पर नज़र डाली।", "Shivam ne har cheez par nazar daali."
def J(dev, rom): return (dev + " " + JAGAH[0], rom + " " + JAGAH[1])

